import {decorateSkill109} from './hud109.js';
const layouts=fetch('skill-layout110.json').then(r=>r.json());
const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
let lastBranch110=1,lastSkill110=0,lastInner110=0,lastPalace110=0;
export async function nativeSkillsPanel110(body,{state,button,mutate,error}){
 const generation=body.dataset.generation110;const layout=await layouts;if(!body.isConnected||body.dataset.panel110!=='skills'||body.dataset.generation110!==generation)return;body.classList.add('nativeSkills110');
 const left=make('section',undefined,'skillNativeLeft110'),tree=make('div',undefined,'skillTree110'),tabs=make('nav',undefined,'skillTabs110'),right=make('section',undefined,'skillDetail110');
 left.append(make('b','技能点 '+state.learning.points),tree,tabs);body.append(left,right);
 const all=state.systems.skillTree,branches=layout[state.character.profession]??[],active=state.skills.filter(k=>k.id!==20002&&k.id<4000&&k.id%10===0);
 const detail=k=>{lastSkill110=k.id;right.replaceChildren(make('h3',k.name),make('p',`${k.kind==='passive'?'被动技能':'主动技能'} · ${k.level}级`),make('p',k.description));
  if(k.next)right.append(make('p',`下级需求：人物${k.next.requiredLevel}级 · 1技能点${k.next.book?' · '+k.next.bookName:''}${k.next.reason?'\n'+k.next.reason:''}`));
  right.append(button(k.next?'学习 / 升级':'已满级',()=>mutate({type:'learn',skill:k.id}),!k.next||!!k.next.reason));
  if(active.some(s=>s.id===k.id)){const on=state.preferences.hotbar.includes(k.id);right.append(button(on?'移出技能快捷栏':'装入技能快捷栏',()=>mutate({type:'preferences',hotbar:on?state.preferences.hotbar.filter(id=>id!==k.id):[...state.preferences.hotbar,k.id]}),!on&&state.preferences.hotbar.length>=6),button(state.preferences.primary===k.id?'已设为普攻键':'放到普攻键',()=>mutate({type:'preferences',primary:k.id}),state.preferences.primary===k.id));}
  right.append(make('h3','手机快捷操作'),make('p','点击左侧原版技能树查看与学习；快捷栏和普攻位置可独立配置。'),button('普攻键恢复普通攻击',()=>mutate({type:'preferences',primary:0}),!state.preferences.primary));
 };
 function select(tab){lastBranch110=tab.id;tree.replaceChildren();tree.style.backgroundImage=`url("${tab.background}")`;for(const b of tabs.children)b.classList.toggle('selected109',+b.dataset.branch===tab.id);
  const entries=tab.skills.length?tab.skills:all.filter(k=>!branches.some(b=>b.skills.some(s=>s.id===k.id))).map((k,i)=>({id:k.id,row:1+Math.floor(i/3),column:i%3+1}));
  for(const p of entries){const k=all.find(k=>k.id===p.id);if(!k)continue;const b=button('',()=>detail(k));decorateSkill109(b,k);b.className='nativeSkill110'+(!k.level?' unlearned110':'');b.dataset.skill=k.id;b.style.left=((70+(p.column-1)*93)/324*100)+'%';b.style.top=((44+(p.row-1)*68)/440*100)+'%';tree.append(b);}
  const remembered=all.find(k=>k.id===lastSkill110&&entries.some(e=>e.id===k.id))??all.find(k=>entries.some(e=>e.id===k.id));if(remembered)detail(remembered);
 }
 for(const tab of branches){const b=button(tab.name,()=>select(tab));b.dataset.branch=tab.id;tabs.append(b);}select(branches.find(b=>b.id===lastBranch110)??branches[0]);
}
