let lastBridgeSkillBranch114=0,lastBridgeSkill114=0,lastBridgeProfession114=0;
export async function pcSkillsPanel114(body,{state,button,mutate}){
 const generation=body.dataset.generation110;
 const [layout,icons]=await Promise.all([layouts,fetch('skill-icons110.json').then(r=>r.json())]);
 if(!body.isConnected||body.dataset.panel110!=='skills'||body.dataset.generation110!==generation)return;
 body.classList.add('nativeSkills110');
 const left=make('section',undefined,'skillNativeLeft110'),tree=make('div',undefined,'skillTree110'),
  tabs=make('nav',undefined,'skillTabs110'),right=make('section',undefined,'skillDetail110');
 let activeConfirmation=null,detailVersion=0;
 function dismissConfirmation(){
  const current=activeConfirmation;activeConfirmation=null;
  if(current){current.overlay.remove();current.restore();}
  left.inert=false;right.inert=false;
 }
 const points=state.learning?.points;
 left.append(make('b',Number.isInteger(points)&&points>=0?
  `技能点 ${points}`:'技能点待同步'),tree,tabs);body.append(left,right);
 const learned=(state.skills??[]).filter(k=>Number.isInteger(Number(k.id))&&Number(k.level)>0);
 const byId=new Map(learned.map(k=>[Number(k.id),k]));
 const preferences=state.preferences??{};
 const pcReady=(state.skills??[]).filter(k=>{const id=Number(k.id),
  maximum=bridgeBindableSkills114[String(id)];
  return Number(k.level)>0&&Number(k.level)<=maximum;});
 const pcStart=Number(state.character?.profession)*1000+100;
 const pcSuggested=pcReady.filter(k=>{const id=Number(k.id);
  return id>=pcStart&&id<pcStart+300&&id%10===0;});
 const hotbar=preferences.hotbarConfigured?
  (Array.isArray(preferences.hotbar)?preferences.hotbar:[]):
  pcSuggested.slice(0,6).map(k=>k.id);
 const primary=Number(preferences.primary??20002);
 const branches=layout[state.character?.profession]??[];
 if(!branches.length){right.append(make('p','当前职业没有对应的原版技能树。'));return;}
 if(lastBridgeProfession114!==state.character.profession){
  lastBridgeProfession114=state.character.profession;lastBridgeSkillBranch114=0;lastBridgeSkill114=0;
 }
 const treeIds=new Set(branches.flatMap(tab=>tab.skills.map(p=>p.id)));
 const extra=learned.filter(k=>!treeIds.has(Number(k.id)));
 const nameOf=(id,k)=>k?.name||bridgeSkillNames114[id]||`技能 ID ${id}`;
 const bindable=id=>{
  const level=Number(byId.get(id)?.level),maximum=bridgeBindableSkills114[id];
  return Number.isInteger(level)&&level>=1&&Number.isInteger(maximum)&&level<=maximum;
 };
 function bindingSummary(){
  const section=make('section',undefined,'skillBindings114');
  section.append(make('p',`普攻键：${primary===20002?'普通攻击':
   nameOf(primary,byId.get(primary))+(byId.has(primary)?` Lv.${byId.get(primary).level}`:' · 等级未同步')}`));
  section.append(make('p',`技能快捷栏 ${hotbar.length}/6：${hotbar.length?
   hotbar.map((id,index)=>`${index+1}. ${nameOf(id,byId.get(id))}`+
    (byId.has(id)?` Lv.${byId.get(id).level}`:' · 等级未同步')).join(' · '):'未配置'}`));
  return section;
 }
 function detail(id,knownIcon){
  dismissConfirmation();const selectedVersion=++detailVersion,selectedRevision=state.revision;
  lastBridgeSkill114=id;
  const k=byId.get(id),name=nameOf(id,k),info=bridgeSkillDetails114[id];
  const level=Number(k?.level??0),current=info?.levels?.[Number.isInteger(level)&&level>0?level-1:0];
  const next=info?.levels?.[k?level:0];
  const learning=state.learning??{},study=learning.studyOptions?.[String(id)];
  const needsBook=Number.isInteger(study?.bookId)&&study.bookId>0;
  const bookName=needsBook?(typeof study.bookName==='string'&&study.bookName.trim()?
   study.bookName.trim():`技能书 ${study.bookId}`):'';
  right.replaceChildren(make('h3',name),make('p',k?`已学 ${k.level} 级`:'尚未学习'));
  if(current?.description)right.append(make('p',current.description));
  if(next&&(!k||level<info.maxLevel)){
   const conditions=[];
   const required=Number.isInteger(study?.requiredLevel)?study.requiredLevel:next.needLevel;
   if(required>0)conditions.push(`人物 ${required} 级`);
   if(Number.isInteger(study?.cost)&&study.cost>0)conditions.push(`${study.cost} 技能点`);
   if(needsBook){
    const amount=Number.isInteger(study.bookCost)&&study.bookCost>0?`需 ${study.bookCost} 本`:'需求数量待确认';
    const held=Number.isInteger(study.bookCount)&&study.bookCount>=0?
     `主背包已有 ${study.bookCount} 本`:'主背包库存待同步';
    conditions.push(`${bookName}：${amount}，${held}`);
   }
   if(conditions.length)right.append(make('p',`${k?'下级需求':'学习需求'}：${conditions.join(' · ')}`));
  }
  let studyReason='';
  if(learning.studyUnknown)studyReason='上次学习结果待确认，请重新登录后核对技能等级和技能点。';
  else if(learning.studyPending)studyReason='正在等待区服确认学习结果。';
  else if(study?.eligible===false&&study.reason)studyReason=study.reason;
  else if(info&&level>=info.maxLevel)studyReason='此技能已满级。';
  else if(!learning.studyEnabled)studyReason=learning.studyReason||'技能学习尚未开放。';
  else if(!next||!study)studyReason=study?.reason||'此技能的学习条件尚未核实。';
  else if(!Number.isInteger(study.currentLevel)||study.currentLevel!==level)
   studyReason='技能等级正在同步，请稍后再试。';
  else if(!Number.isInteger(study.nextLevel)||study.nextLevel!==level+1||
   !Number.isInteger(study.requiredLevel)||study.requiredLevel<0||
   !Number.isInteger(study.cost)||study.cost<1)studyReason='此技能的学习条件尚未核实。';
  else if(!study.eligible)studyReason=study.reason||'尚未满足此技能的学习条件。';
  else if(needsBook&&(study.bookCost!==1||!Number.isInteger(study.bookCount)||study.bookCount<0))
   studyReason='技能书学习条件正在同步，请稍后再试。';
  else if(needsBook&&study.bookCount<study.bookCost)studyReason=`主背包缺少 ${bookName}，需要 ${study.bookCost} 本。`;
  else if(needsBook&&(!Number.isInteger(study.bookInstance?.instanceId)||study.bookInstance.instanceId<=0||
   !Number.isInteger(study.bookInstance?.count)||study.bookInstance.count<1))
   studyReason='技能书库存正在同步，请稍后再试。';
  else if(!Number.isInteger(points)||points<study.cost)studyReason='技能点不足。';
  else if(!Number.isInteger(state.character?.level)||state.character.level<study.requiredLevel)
   studyReason=`需要人物 ${study.requiredLevel} 级。`;
  let studySubmitted=false;
  const detailCurrent=()=>body.isConnected&&right.isConnected&&body.contains(right)&&
   body.dataset.panel110==='skills'&&body.dataset.generation110===generation&&
   selectedVersion===detailVersion&&selectedRevision===state.revision&&lastBridgeSkill114===id;
  const submitStudy=bookConfirmation=>{
   if(studyReason||studySubmitted||!detailCurrent())return;
   studySubmitted=true;learnButton.disabled=true;learnButton.textContent='等待学习结果';
   setTimeout(()=>{studySubmitted=false;if(detailCurrent()){learnButton.disabled=!!studyReason;learnButton.textContent='学习 / 升级';}},800);
   dismissConfirmation();
   return mutate({type:'skill_study',skillId:id,expectedLevel:study.currentLevel,
    ...(bookConfirmation?{bookConfirmation}:{})});
  };
  const learnButton=button('学习 / 升级',()=>{
   if(studyReason||studySubmitted||activeConfirmation||!detailCurrent())return;
   if(!needsBook)return submitStudy();
   const bookConfirmation={bookId:study.bookId,count:study.bookCost,
    instanceId:study.bookInstance.instanceId,stackCount:study.bookInstance.count};
   const overlay=make('div',undefined,'bridgeStudyOverlay114'),
    dialog=make('section',undefined,'bridgeStudyConfirm114'),
    heading=make('div',undefined,'panelhead'),content=make('div',undefined,'bridgeStudyConfirmBody114'),
    actions=make('div',undefined,'buttons');
   dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');
   dialog.setAttribute('aria-label','确认消耗技能书');
   heading.append(make('h2','确认学习'));
   content.append(make('h3',name),make('p',`技能等级：${study.currentLevel} → ${study.nextLevel}`),
    make('p',`消耗：${bookName} ${study.bookCost} 本`),
    make('p',`消耗：${study.cost} 技能点`),make('p','确认后将扣除以上技能书和技能点。'));
   const cancel=button('取消',()=>{
    if(activeConfirmation?.overlay===overlay){dismissConfirmation();if(detailCurrent())learnButton.focus?.();}
   });
   const confirm=button('确认学习',()=>{
    if(activeConfirmation?.overlay!==overlay||!detailCurrent())return;
    if(study.bookId!==bookConfirmation.bookId||study.bookCost!==bookConfirmation.count||
     study.bookInstance?.instanceId!==bookConfirmation.instanceId||
     study.bookInstance?.count!==bookConfirmation.stackCount){dismissConfirmation();return;}
    confirm.disabled=true;cancel.disabled=true;return submitStudy(bookConfirmation);
   });
   actions.append(cancel,confirm);content.append(actions);dialog.append(heading,content);overlay.append(dialog);
   overlay.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();cancel.onclick();}};
   overlay.onpointerdown=e=>e.stopPropagation();
   activeConfirmation={overlay,restore:()=>{learnButton.disabled=!!studyReason||studySubmitted;}};
   learnButton.disabled=true;left.inert=true;right.inert=true;body.append(overlay);cancel.focus?.();
  },!!studyReason);
  right.append(learnButton);
  if(k&&bindable(id)){
   const position=hotbar.indexOf(id);
   right.append(button(position>=0?'移出技能快捷栏':'装入技能快捷栏',
    ()=>mutate({type:'preferences',hotbar:position>=0?
     hotbar.filter(value=>value!==id):[...hotbar,id]}),position<0&&hotbar.length>=6),
    button(primary===id?'已设为普攻键':'放到普攻键',
     ()=>mutate({type:'preferences',primary:id}),primary===id));
  }
  if(studyReason)right.append(make('p',studyReason));
  right.append(make('h3','手机快捷操作'),
   make('p','点击左侧技能树查看与学习；快捷栏和普攻位置可独立配置。'),
   bindingSummary(),button('普攻键恢复普通攻击',
    ()=>mutate({type:'preferences',primary:20002}),primary===20002),
   make('p',state.meta?.combat?.enabled===true&&state.meta.combat.kinds?.includes('skill')&&
    state.meta.combat.skillIds?.includes(Number(id))&&k?
    '短按快捷技能直接施放并自动选择范围内的敌人；拖动技能按钮可指定落点。':
    '技能施放尚未接入 PC 区服。'));
  if(k&&!bindable(id))right.append(make('p','此技能不在已核实的主动技能快捷键清单中。'));
  if(!knownIcon)right.append(make('p','此技能在原版 APK 中没有核实的同 ID 图标。'));
 }
 function select(tab){
  dismissConfirmation();++detailVersion;
  lastBridgeSkillBranch114=tab.id;tree.replaceChildren();tree.style.backgroundImage=`url("${tab.background}")`;
  for(const b of tabs.children)b.classList.toggle('selected109',+b.dataset.branch===tab.id);
  const entries=tab.skills.length?tab.skills:extra.map((k,i)=>({id:Number(k.id),row:1+Math.floor(i/3),column:i%3+1}));
  for(const p of entries){
   const k=byId.get(p.id),name=nameOf(p.id,k),icon=icons[p.id],knownIcon=icon===`ui110/skill-${p.id}.png`;
   const b=button('',()=>detail(p.id,knownIcon));
   b.className='nativeSkill110'+(k?'':' unlearned110');b.dataset.skill=p.id;
   b.style.left=((70+(p.column-1)*93)/324*100)+'%';
   b.style.top=((44+(p.row-1)*68)/440*100)+'%';
   if(knownIcon){const img=make('img');img.src=icon;img.alt='';b.append(img);}
   else b.append(make('span','?'));
   // The level circle belongs to the 324x438 background, not the icon box.
   // Anchor both learned and unlearned text in that same coordinate system.
   const levelLabel=make('small',k?`Lv.${k.level}`:'未学','bridgeSkillLevel114');
   levelLabel.style.left=([100,193,284][p.column-1]/324*100)+'%';
   levelLabel.style.top=((73+(p.row-1)*68)/438*100)+'%';
   levelLabel.setAttribute('aria-hidden','true');
   b.title=`${name} · ${k?`${k.level}级`:'未学习'}${knownIcon?'':' · 图标未核实'}`;
   b.setAttribute('aria-label',b.title);tree.append(b,levelLabel);
  }
  const chosen=entries.find(p=>p.id===lastBridgeSkill114)||entries.find(p=>byId.has(p.id))||entries[0];
  if(chosen)detail(chosen.id,icons[chosen.id]===`ui110/skill-${chosen.id}.png`);
  else right.replaceChildren(make('p','此分支没有已学技能。'));
 }
 for(const tab of branches){const b=button(tab.name,()=>select(tab));b.dataset.branch=tab.id;tabs.append(b);}
 const initial=branches.find(tab=>tab.id===lastBridgeSkillBranch114)||
  branches.find(tab=>tab.skills.some(p=>byId.has(p.id)))||branches[0];select(initial);
}

export function innerPanel110(body,{state,button,mutate}){
 body.classList.add('innerPanel110');const list=make('nav',undefined,'innerList110'),map=make('section',undefined,'innerMap110'),details=make('section',undefined,'innerDetail110');body.append(list,map,details);
 const pos=[[35,50],[35,73],[50,50],[35,28],[19.5,50]],names=['中宫','太阳','少阳','太阴','少阴'];
 const select=h=>{lastInner110=h.id;map.replaceChildren(make('h3',h.name));map.style.backgroundImage='url("ui110/internalstrengthinterface-neigong1.png")';for(const b of list.children)b.classList.toggle('selected109',+b.dataset.inner===h.id);
  function choose(p){lastPalace110=p.palace;details.replaceChildren(make('h3',h.name+' · '+names[p.palace]),make('p',h.learned?(h.active?'已激活':'已学习，未激活'):'40级使用帝王丹开启，学习对应心法后修炼。'),make('p',`${names[p.palace]} ${p.level}级`));if(h.learned)details.append(make('p',`升级消耗：${p.cost??0}金币 · ${p.xp??0}经验${p.reason?'\n'+p.reason:''}`),button('修炼升级',()=>mutate({type:'inner',id:h.id,palace:p.palace}),!!p.reason),button(h.active?'关闭内功':'激活内功',()=>mutate({type:'inner-activate',id:h.id,enabled:!h.active})));}
  for(const p of h.palaces){const b=button(names[p.palace]+'\n'+p.level+'级',()=>choose(p));b.className='palace110';b.style.left=pos[p.palace][0]+'%';b.style.top=pos[p.palace][1]+'%';map.append(b);}choose(h.palaces[lastPalace110]??h.palaces[0]);};
 for(const h of state.systems.inner){const b=button(h.name+(h.active?' · 激活':''),()=>select(h));b.dataset.inner=h.id;list.append(b);}select(state.systems.inner.find(h=>h.id===lastInner110)??state.systems.inner.find(h=>h.learned)??state.systems.inner[0]);
}
